// figma/naming.mjs
function normalizeFigmaComponentName(name) {
  return name.split(/[^A-Za-z0-9]+/).filter(Boolean).map((segment) => segment.charAt(0).toUpperCase() + segment.slice(1)).join("");
}
function normalizeFigmaPropName(name) {
  const segments = name.split(/[^A-Za-z0-9]+/).filter(Boolean).map((segment) => segment.charAt(0).toLowerCase() + segment.slice(1));
  if (segments.length === 0) {
    return "";
  }
  return [segments[0], ...segments.slice(1).map((segment) => segment.charAt(0).toUpperCase() + segment.slice(1))].join("");
}

