    return "feedback";
  }
  if ([
    "tooltip",
    "guard-dialog",
    "alert",
    "hierarchy-picker-modal",
    "modal",
    "side-sheets"
  ].includes(componentId)) {
    return "overlay";
  }
  if ([
    "table",
    "table-header",
    "table-header-control",
    "table-row-control",
    "table-cell",
    "category-table-field"
  ].includes(componentId)) {
    return "data-grid";
  }
  if ([
    "admin-shell",
    "admin-page-header",
    "admin-search-area",
    "section-block"
  ].includes(componentId)) {
    return "layout-shell";
  }
  if ([
    "form-field",
    "label",
    "admin-form-section",
    "field-stack",
    "translation-field-row",
    "conditional-field-group",
    "repeatable-field-list",
    "upload-group",
    "upload"
  ].includes(componentId)) {
    return "form-composition";
  }
  if ([
    "admin-split-workspace",
    "tree-header",
    "tree-toolbar",
    "tree-panel",
    "tree-detail-panel",
    "tree",
    "selection-summary-bar",
    "schedule-table-editor",
