function resolveDefaultDocArchetype(family, componentId) {
  if ([
    "icon-set",
    "section-status-tag",
    "table-header",
    "table-header-control",
    "table-row-control"
  ].includes(componentId)) {
    return "token-bridge-primitive";
  }
  if (family === "navigation") {
    return "compound-navigation";
  }
  if (family === "selection") {
    return "compound-selection";
  }
  if (family === "overlay" || family === "workspace") {
    return "overlay-workspace";
  }
  if (family === "layout-shell" || family === "form-composition" || family === "data-grid") {
    return "field-slot-composition";
  }
  return "single-variant";
}
