.mcds-modal-root .ant-modal-container {
  padding: 0;
  border-radius: var(--mcds-component-modal-border-radius);
  background: var(--mcds-color-white);
  box-shadow: var(--mcds-component-modal-shadow);
  overflow: hidden;
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  width: 100%;
  min-width: 0;
  max-width: 100%;
  min-height: 100%;
  overflow-x: hidden;
}

body {
  margin: 0;
  font-family: var(--mcds-font-family);
  color: var(--mcds-color-gray-10);
}

button,
input,
select,
textarea {
  font: inherit;
}

input::placeholder,
textarea::placeholder {
  color: var(--mcds-color-gray-500);
  opacity: 1;
}
